# What this script does  :: Turns the hex string into a 48 x 48 binary grid.
# ----------------------------------------------------------------------------
# The hexadecimal string you provided
hex_string = ""

# Convert hex to a binary string, ensuring it has 2304 digits (48*48)
binary_string = bin(int(hex_string, 16))[2:].zfill(2304)

# Print the 48x48 grid
print("Your 48x48 starting grid:")
for i in range(48):
    # Print each row of 48 characters
    print(binary_string[i*48 : (i+1)*48])